void unit_test_createNFA_successful_creation(void) {
    // Call the function under test
    struct NFA* nfa = createNFA();

    // Assert that the NFA was created successfully
    TEST_ASSERT_NOT_NULL(nfa);

    // Check initial values as per specification
    TEST_ASSERT_EQUAL_INT(0, nfa->stateCount);      // Should be 0 before addState increments
    TEST_ASSERT_NOT_NULL(nfa->statePool);
    TEST_ASSERT_EQUAL_INT(0, nfa->ruleCount);
    TEST_ASSERT_NOT_NULL(nfa->rulePool);
    TEST_ASSERT_EQUAL_INT(0, nfa->CSCount);
    TEST_ASSERT_NOT_NULL(nfa->currentStates);
    TEST_ASSERT_EQUAL_INT(0, nfa->subCount);
    TEST_ASSERT_NOT_NULL(nfa->subs);
    TEST_ASSERT_EQUAL_INT(0, nfa->wrapperFlag);

    // The function adds two states, so after creation, stateCount should be 2
    // (Assuming addState increments stateCount)
    TEST_ASSERT_GREATER_THAN(1, nfa->stateCount);

    // Cleanup: free the NFA and all associated resources
    destroyNFA(nfa);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_createNFA_successful_creation);
    return UNITY_END();
}


